["lino","Lino molido","semilla","",0,0,6,"Molido y mezclado en gachas, yogur o purés.","Molido en gachas, yogur o masas.","Molido o en recetas.","Entero pasa sin digerir: muélelo. Empieza con poca cantidad por la fibra."],
["canamo","Semillas de cáñamo","semilla","",0,1,6,"Peladas y molidas sobre purés o yogur.","Peladas, molidas o enteras mezcladas en comidas húmedas.","Peladas, espolvoreadas.","Usa siempre semillas peladas de uso alimentario."],
["pipas_calabaza","Pipas de calabaza","semilla","",2,1,6,"Molidas finas y mezcladas en purés o gachas.","Molidas o en crema.","Molidas. Enteras, no antes de los 4 años.","Enteras son pequeñas y duras: riesgo alto de atragantamiento. Buena fuente de hierro y zinc molidas."],
["mostaza","Mostaza","otros","",0,0,12,"No ofrecer todavía.","No ofrecer todavía.","Muy poca cantidad, en salsas caseras.","La mostaza es alérgeno de declaración obligatoria en la UE. La comercial lleva sal y vinagre."],
// GRASAS Y OTROS
["agua","Agua","otros","",0,0,6,"Unos sorbos en vaso abierto o con pajita durante las comidas.","En vaso abierto, a demanda en las comidas.","Agua como bebida principal junto con la leche.","Desde el inicio de la alimentación complementaria. Antes de los 6 meses, solo leche materna o de fórmula."],
["caldo_casero","Caldo casero sin sal","otros","",0,0,6,"Para cocer arroz, pasta o hacer purés.","En sopas y guisos.","En sopas y guisos.","Los cubitos y caldos de brick llevan mucha sal: mejor caseros, sin sal."],
["vinagre","Vinagre","otros","",0,0,6,"Unas gotas para dar sabor a verduras cocinadas.","Pocas gotas como condimento.","Como condimento.","Alternativa a la sal para dar sabor. En poca cantidad."],
["levadura_nutricional","Levadura nutricional","otros","",0,0,6,"Espolvoreada en purés, pasta o verdura.","Espolvoreada para dar sabor a queso.","Espolvoreada.","Da sabor sin sal. No es levadura de panadería y no fermenta."],
["cacao","Cacao puro en polvo","otros","",0,0,12,"No ofrecer todavía.","No ofrecer todavía.","Cacao puro sin azúcar, una pizca en gachas o yogur.","El cacao soluble lleva sobre todo azúcar. Tiene algo de estimulantes: en pequeña cantidad."],
["aceite_girasol","Aceite de girasol","otros","",0,0,6,"Para cocinar, en poca cantidad.","Para cocinar.","Para cocinar.","Para el día a día, mejor aceite de oliva virgen extra. El de girasol alto oleico, para freír."],
["aceite_coco","Aceite de coco","otros","",0,0,6,"Ocasional y en poca cantidad para cocinar.","Ocasional para cocinar.","Ocasional.","Rico en grasa saturada. No es mejor que el aceite de oliva."],
["bebida_avena","Bebida de avena","otros","",0,0,6,"Solo en cocina (gachas, masas). No como bebida.","Solo en cocina.","Puede tomarla, pero no sustituye a la leche si no está enriquecida en calcio.","No sustituye a la leche materna o de fórmula antes del año. Elige sin azúcar y enriquecida en calcio. Puede llevar gluten."],
["bebida_soja","Bebida de soja","otros","soja",0,0,6,"Solo en cocina (gachas, purés). No como bebida.","Solo en cocina.","Sin azúcar y enriquecida en calcio, si la familia la usa.","Contiene soja, alérgeno. No sustituye a la leche materna o de fórmula antes del año."],
["bebida_arroz","Bebida de arroz","evitar","",0,0,72,"No ofrecer.","No ofrecer.","No ofrecer.","AESAN desaconseja las bebidas de arroz en menores de 6 años por su contenido en arsénico."],
["cafe_te","Café, té y bebidas con cafeína","evitar","",0,0,144,"No ofrecer.","No ofrecer.","No ofrecer.","La cafeína no es adecuada en niños. El té también reduce la absorción del hierro."],
// MEJOR ESPERAR
["frutos_secos_enteros","Frutos secos enteros","evitar","",2,0,60,"No ofrecer enteros ni troceados. Solo molidos o en crema.","No ofrecer enteros ni troceados.","No ofrecer enteros ni troceados.","La AEP desaconseja los frutos secos enteros antes de los 5 años por riesgo de asfixia. Molidos o en crema se pueden dar desde el inicio."],
["caramelos","Caramelos duros y chicles","evitar","",2,0,60,"No ofrecer.","No ofrecer.","No ofrecer.","Riesgo alto de asfixia, además del azúcar."],
["gominolas","Gominolas y chucherías","evitar","",2,0,60,"No ofrecer.","No ofrecer.","No ofrecer.","Pegajosas y elásticas, se adaptan a la vía aérea. Mucho azúcar y aditivos."],
["refrescos","Refrescos y bebidas azucaradas","evitar","",0,0,24,"No ofrecer.","No ofrecer.","No ofrecer.","Azúcar sin nada que aportar. Los de cola y las bebidas energéticas, además, llevan cafeína."],
["ultraprocesados","Bollería, galletas y ultraprocesados","evitar","",1,0,24,"No ofrecer.","No ofrecer.","Mejor evitar.","Azúcar, sal y grasas de mala calidad. Incluye galletas tipo María, cereales de desayuno azucarados y nuggets."],
["patatas_bolsa","Patatas fritas de bolsa y snacks salados","evitar","",2,0,36,"No ofrecer.","No ofrecer.","No ofrecer.","Mucha sal y grasa. Son duras y se rompen en trozos afilados."],
["leche_cruda","Leche cruda y quesos sin pasteurizar","evitar","leche",0,0,60,"No ofrecer.","No ofrecer.","No ofrecer.","Riesgo de listeria, E. coli y otras bacterias. Comprueba en la etiqueta que el queso sea de leche pasteurizada."],
["brotes_crudos","Brotes y germinados crudos","evitar","",1,0,60,"No ofrecer.","No ofrecer.","No ofrecer crudos. Bien cocinados, sí.","Pueden llevar bacterias como E. coli o salmonela. Si los usas, cocínalos bien."]
