const SYMPTOMS = ["Rojez alrededor de la boca","Habones o ronchas","Hinchazón de labios u ojos","Vómitos","Diarrea","Tos o pitos","Picor","Irritabilidad","Estreñimiento"];

const GUIDES = [
 {id:"g1",n:"¿Está lista para empezar?",h:`<p>La alimentación complementaria se empieza hacia los <b>6 meses</b>, cuando el bebé muestra estas señales:</p><ul><li>Se sienta con poco apoyo y mantiene bien la cabeza.</li><li>Muestra interés por la comida y lleva cosas a la boca.</li><li>Ha perdido el reflejo de expulsar con la lengua todo lo que entra.</li><li>Coordina ojo, mano y boca.</li></ul><p>La leche (materna o de fórmula) sigue siendo su alimento principal hasta el año. La comida al principio es para explorar.</p>`},
 {id:"g2",n:"Arcada o atragantamiento",h:`<p><b>La arcada es normal</b> y protege: el bebé hace ruido, tose, saca la lengua, se pone rojo. Mantén la calma y deja que lo resuelva solo.</p><p><b>El atragantamiento es silencioso</b>: no puede toser ni llorar, se pone pálido o azulado, mira asustado. Es una emergencia: <b>llama al 112</b> y empieza las maniobras de desobstrucción para lactantes.</p><p>Muy recomendable: un curso de primeros auxilios pediátricos para ambos.</p><p>Siempre: sentada recta, vigilada, sin distracciones, y nunca comiendo en el coche o tumbada.</p>`},
 {id:"g3",n:"Cómo cortar según la edad",h:`<p><b>6 a 9 meses:</b> agarra con toda la mano. Ofrece tiras largas del tamaño de dos dedos de adulto, blandas (que se aplasten entre el pulgar y el índice).</p><p><b>9 a 12 meses:</b> aparece la pinza. Trocitos pequeños del tamaño de un garbanzo, blandos.</p><p><b>12 meses en adelante:</b> trozos pequeños y variedad de texturas.</p><p><b>Siempre:</b> los alimentos redondos (uva, cereza, tomate cherry, arándanos) en cuartos a lo largo; nada duro, crujiente y redondo; frutos secos solo molidos o en crema hasta los 5 años.</p>`},
 {id:"g4",n:"Introducir alérgenos",h:`<p>La recomendación actual es <b>no retrasar</b> los alimentos alergénicos: introducirlos desde los 6 meses, uno nuevo cada vez, y después mantenerlos en la dieta.</p><ul><li>Ofrece el alérgeno nuevo por la mañana, para poder observar durante el día.</li><li>Empieza con poca cantidad y ve aumentando.</li><li>Espera unos días antes del siguiente alérgeno nuevo.</li><li>Una vez tolerado, ofrécelo con regularidad (un par de veces por semana).</li></ul><p>Si tiene eccema importante o ya ha tenido una alergia, habla antes con la pediatra.</p>`},
 {id:"g5",n:"Reacciones: cuándo preocuparse",h:`<p><b>Leve:</b> rojez o algunos habones alrededor de la boca o en la zona de contacto. Para el alimento, haz fotos y coméntalo con la pediatra.</p><p><b>Grave, llama al 112:</b> hinchazón de cara, labios o lengua; dificultad para respirar, tos persistente o pitos; vómitos repetidos; palidez, decaimiento o que esté muy flojo; habones por todo el cuerpo.</p>`},
 {id:"g6",n:"Qué evitar el primer año",h:`<ul><li><b>Miel</b> (riesgo de botulismo) antes de los 12 meses.</li><li><b>Sal y azúcar</b> añadidos.</li><li><b>Leche de vaca como bebida</b> antes de los 12 meses.</li><li><b>Espinacas y acelgas</b> antes del año (nitratos).</li><li><b>Pez espada, tiburón, atún rojo y lucio</b> hasta los 10 años (mercurio).</li><li><b>Bebidas de arroz</b> antes de los 6 años, y variar cereales por el arsénico.</li><li><b>Algas</b>, por el exceso de yodo.</li><li>Huevo, carne o pescado crudos o poco hechos, y quesos sin pasteurizar.</li><li><b>Frutos secos enteros</b> antes de los 5 años.</li><li>Zumos, refrescos, ultraprocesados.</li></ul>`},
 {id:"g7",n:"El hierro importa",h:`<p>A partir de los 6 meses las reservas de hierro bajan, así que conviene que <b>cada comida principal tenga un alimento rico en hierro</b>: carne, pescado, huevo, legumbres, tofu, cereales integrales.</p><p>Combínalos con <b>vitamina C</b> (pimiento, tomate, kiwi, naranja, fresa, brócoli) para absorberlo mejor.</p><p>En la pestaña Alimentos puedes filtrar por "Rico en hierro".</p>`},
 {id:"g8",n:"Un día de ejemplo",h:`<p><b>6-7 meses:</b> una comida al día, cuando no tenga sueño ni mucha hambre (más o menos una hora después de la toma).</p><p><b>8-9 meses:</b> dos o tres comidas al día.</p><p><b>10-12 meses:</b> tres comidas y una o dos meriendas, cada vez más parecidas a las de la familia.</p><p>Ofrécele <b>agua en vaso abierto</b> con las comidas. Ella decide cuánto come; vosotros decidís qué y cuándo.</p>`}
];
